from solution import count_Substring_With_Equal_Ends


def test_issue_example_abc():
    """Count all substrings starting and ending with same characters."""
    assert count_Substring_With_Equal_Ends("abc") == 3  # 3 singles = 3


def test_issue_empty_input():
    """Count all substrings starting and ending with same characters."""
    assert count_Substring_With_Equal_Ends("") == 0  # no substrings = 0


def test_issue_single_character():
    """Count all substrings starting and ending with same characters."""
    assert count_Substring_With_Equal_Ends("a") == 1  # 1 single = 1


def test_issue_two_identical_characters():
    """Count all substrings starting and ending with same characters."""
    assert count_Substring_With_Equal_Ends("aa") == 3  # 2*3//2 = 3


def test_issue_all_same_four():
    """Count all substrings starting and ending with same characters."""
    assert count_Substring_With_Equal_Ends("aaaa") == 10  # 4*5//2 = 10


def test_issue_all_distinct_four():
    """Count all substrings starting and ending with same characters."""
    assert count_Substring_With_Equal_Ends("abcd") == 4  # 4 singles = 4


def test_issue_palindrome_aba():
    """Count all substrings starting and ending with same characters."""
    assert count_Substring_With_Equal_Ends("aba") == 4  # 2*3//2 + 1 = 3 + 1 = 4


def test_issue_alternating_ababa():
    """Count all substrings starting and ending with same characters."""
    assert count_Substring_With_Equal_Ends("ababa") == 9  # 3*4//2 + 2*3//2 = 6 + 3 = 9


def test_issue_prefix_repeat_aab():
    """Count all substrings starting and ending with same characters."""
    assert count_Substring_With_Equal_Ends("aab") == 4  # 2*3//2 + 1 = 3 + 1 = 4


def test_issue_mixed_repeat_abcab():
    """Count all substrings starting and ending with same characters."""
    assert count_Substring_With_Equal_Ends("abcab") == 7  # 2*3//2 + 2*3//2 + 1 = 3 + 3 + 1 = 7


def test_contract_singletons_always_counted():
    """Every single-character substring starts and ends with the same character."""
    assert count_Substring_With_Equal_Ends("wxyz") == 4  # 4 singles = 4


def test_contract_repeated_chars_combine():
    """Count all substrings starting and ending with same characters."""
    assert count_Substring_With_Equal_Ends("bbcc") == 6  # 2*3//2 + 2*3//2 = 3 + 3 = 6
